update pages set contenu = '{"sections":[{"type":"heros","h1":"La maintenance industrielle dans le Rhône, du Beaujolais à Feyzin","mecanisme":"Le département tient sur trois bandes industrielles qui ne se ressemblent pas : la chimie lourde au sud, entre Saint-Fons, Feyzin et Pierre-Bénite, la mécanique et la logistique à l''est, de Saint-Priest à Genas et Corbas, l''agroalimentaire et l''emballage au nord, dans le val de Saône autour de Villefranche. Notre agence de Lyon couvre les trois, sans changer de méthode.","cta":"Faire chiffrer ma maintenance dans le Rhône","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"+ 100","libelle":"collaborateurs, mécaniciens, électriciens, automaticiens, roboticiens"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"}]},{"type":"probleme","punchline":"Au sud du département, une intervention mal préparée ne démarre pas. À l''est, elle démarre trop tard. Dans les deux cas, la production paie la différence.","puces":[{"accroche":"Le sud impose le plan avant le geste.","texte":"Installations classées, procédés continus, consignations et protocoles de sécurité : une visite qui n''a pas été cadrée n''entre pas en zone."},{"accroche":"L''est concentre la densité et la concurrence.","texte":"Saint-Priest, Corbas, Genas, Vaulx-en-Velin : la plus forte concentration d''ateliers et de plateformes du département, et des techniciens que tout le monde cherche."},{"accroche":"Le nord vit au rythme des campagnes.","texte":"Val de Saône et Beaujolais : conditionnement, embouteillage, emballage, avec des pics saisonniers où l''équipement doit être prêt avant, pas réparé pendant."},{"accroche":"Le fleuve structure les accès.","texte":"Port Édouard-Herriot, quais, sites contraints : manutention lourde et créneaux de livraison se préparent, jamais un vendredi après-midi."},{"accroche":"Réparer sans comprendre revient plus cher.","texte":"Sans recherche de cause racine, la même défaillance repart pour un tour, et le budget correctif dérape."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"L''entrée en site classé cadrée avant le départ","texte":"plan de prévention, protocole de sécurité, habilitations, coordination HSE."},"benefice":"Une intervention au sud du département ne se bloque plus sur un point de procédure."},{"prestation":{"accroche":"Un préventif resserré avant les campagnes saisonnières","texte":"du val de Saône et du Beaujolais."},"benefice":"Vous entrez en pic avec un parc préparé, pas avec une liste de réparations en attente."},{"prestation":{"accroche":"Le champ technique complet","texte":"[mécanique](/expertises/mecanique/), [électricité](/expertises/electrique/), [électromécanique](/expertises/electromecanique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/)."},"benefice":"Un seul contrat pour un parc qui mélange pompes de procédé, machines-outils et convoyeurs."},{"prestation":{"accroche":"Automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc","texte":"en appui du technicien présent."},"benefice":"Un défaut d''automate ne devient plus une attente de spécialiste extérieur."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", portée par l''agence de [Lyon](/implantations/lyon/)."},"benefice":"Les installations en service continu sont couvertes la nuit et le week-end."},{"prestation":{"accroche":"Les grands projets pris en charge","texte":"[transfert de production](/offres/chantier/transfert-de-production/), [remise en état](/offres/retrofit/remise-en-etat/), [arrêt planifié](/offres/arret-technique/)."},"benefice":"Regroupement d''ateliers ou déménagement de ligne : un chef de projet unique, des jalons datés."}]},{"type":"deroule","etapes":[{"titre":"La prise de contact","texte":"Panne, dérive ou besoin de travaux, au 04 78 33 72 05 ou par le formulaire. Le rappel arrive dans l''heure aux horaires ouvrés, et qualifie l''équipement, l''accès et les habilitations."},{"titre":"Le devis écrit","texte":"Périmètre, moyens, conditions d''intervention. Ce qui sort du cadre est chiffré avant d''être fait, pas au moment de la facture."},{"titre":"La préparation d''accès","texte":"En site classé, le plan de prévention et le protocole se valident avant le départ du technicien."},{"titre":"L''intervention","texte":"Accueil sécurité, consignation, diagnostic, remplacement de la pièce en cause, essais."},{"titre":"La cause racine","texte":"L''analyse cherche pourquoi la défaillance est arrivée, puis débouche sur un plan d''action chiffré."},{"titre":"Le compte rendu","texte":"Actions, pièces, résultats, préconisations, versés dans votre GMAO, de la première à la dernière visite."}]},{"type":"garanties","puces":[{"accroche":"Un intervenant qui revient","texte":"sur un contrat suivi, le même technicien aussi longtemps que possible, et un profil équivalent briefé sur vos machines en cas d''absence."},{"accroche":"Un niveau technique vérifié en amont","texte":"entretien technique et comportemental, 10 % des candidats retenus. Les résultats d''évaluation vous parviennent avant le premier déplacement."},{"accroche":"Des pièces au prix du marché et un périmètre écrit","texte":"pas de coefficient caché, et un conseil de stock minimal de pièces critiques dimensionné sur vos historiques."}]},{"type":"cta","question":"Besoin d''un mainteneur qui prépare l''accès avant de parler de la panne ?","bouton":"Faire chiffrer ma maintenance dans le Rhône","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Diagnostic sur site et réparation d''un parc machines défaillant, à Lyon, sans rachat de matériel neuf","texte":"PME de production de joints, depuis février 2024","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Six techniciens en permanence sur le contrat de préventif annuel des sites de Lyon","texte":"depuis septembre 2023, prise en charge complète réalisée en un mois","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Un automaticien SIEMENS à temps plein pour le démarrage d''une ligne neuve près de Lyon","texte":"deuxième et troisième trimestres 2025","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Un électromécanicien habilité risque chimique mobilisé 6 mois","texte":"remise en état d''un site de traitement des eaux industrielles","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Un polyvalent intégré sur un parc papier et emballage aux contraintes techniques variées","texte":"2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous sur un site classé Seveso dans la vallée de la chimie ?","reponse":"Oui. Plan de prévention, protocole de sécurité, habilitations électriques à jour, coordination avec votre service HSE : nous entrons dans vos règles, pas dans les nôtres. Les contraintes du site figurent au devis, en préventif comme en curatif."},{"question":"Quelles zones du département couvrez-vous ?","reponse":"La vallée de la chimie au sud, l''est lyonnais de Saint-Priest à Genas et Corbas, Villeurbanne et Vaulx-en-Velin, le val de Saône jusqu''à Villefranche-sur-Saône et les zones d''activité du Beaujolais. Au-delà, le réseau couvre l''Auvergne-Rhône-Alpes puis la France entière, avec un contrat unique."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"Zéro arrêt est chiffré sur devis, avec trois niveaux de couverture et un engagement type de 6 mois renouvelable. Une installation classée du sud du département demande plus de préparation qu''un atelier de l''est, et le devis en tient compte, installation par installation. Le diagnostic de départ est gratuit."},{"question":"Pouvez-vous tenir un poste à demeure dans notre usine ?","reponse":"Oui, c''est l''offre [résidence](/offres/residence/). Le technicien est salarié Migen, intégré à votre équipe et suivi par un référent, avec une prise de poste en 2 à 3 semaines. En cas d''absence, le remplacement s''organise sur vos installations, il ne se cherche pas dans l''urgence."},{"question":"Travaillez-vous dans notre GMAO ?","reponse":"Oui. Chaque intervention y est saisie : historique par équipement, programme de visites, temps passé, pièces, préconisations. Aucun outil parallèle, aucune saisie en double. Les données vous appartiennent et restent lisibles par votre direction."},{"question":"Louez-vous du matériel de remplacement ?","reponse":"Non, ce n''est pas notre métier. Nous entretenons et réparons le vôtre, et nous chiffrons la remise en état quand elle coûte moins cher que le neuf. Si un équipement doit être remplacé, nous le disons avec les chiffres qui le justifient."}]},{"type":"ctaFinal","question":"Besoin de la même méthode sur vos sites du nord et du sud du département ?","bouton":"Faire chiffrer ma maintenance dans le Rhône","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/lyon/rhone/';
